import React from "react";
import { StyleSheet, Text, View, TouchableOpacity } from "react-native";

export function Nota({ item, onPress }) {
  if (!item) {
    return null;
  }

  const categorias = { Pessoal: "#FF924F", Outros: "#00911F", Trabalho: "#2F71EB" };
  const style = styleFunction(categorias["Pessoal"]);

  // Se item for um array [chave, valor] do AsyncStorage
  if (Array.isArray(item) && item.length >= 2) {
    return (
      <TouchableOpacity onPress={onPress}>
        <View style={style.cartao}>
          <Text style={style.texto} numberOfLines={5}>
            {item[1]}
          </Text>
        </View>
      </TouchableOpacity>
    );
  }

  // Se for um objeto com propriedade texto
  if (item && typeof item === 'object' && item.texto) {
    return (
      <TouchableOpacity onPress={onPress}>
        <View style={style.cartao}>
          <Text style={style.texto} numberOfLines={5}>
            {item.texto}
          </Text>
        </View>
      </TouchableOpacity>
    );
  }

  // Fallback para qualquer outro formato
  return (
    <TouchableOpacity onPress={onPress}>
      <View style={style.cartao}>
        <Text style={style.texto} numberOfLines={5}>
          {String(item)}
        </Text>
      </View>
    </TouchableOpacity>
  );
}

const styleFunction = (cor) =>
  StyleSheet.create({
    cartao: {
      borderRadius: 8,
      backgroundColor: "#ffffff",
      paddingVertical: 12,
      paddingHorizontal: 16,
      marginHorizontal: 16,
      marginBottom: 12,
      borderTopWidth: 5,
      borderColor: cor,
      shadowColor: "#000",
      shadowOffset: {
        width: 0,
        height: 2,
      },
      shadowOpacity: 0.23,
      shadowRadius: 2.62,
      elevation: 4,
    },
    texto: {
      lineHeight: 24,
      fontSize: 16,
    },
  });
